# Compute properties of 3s and 5s
def centroid(coords):
    if not coords:
        return (0, 0)
    avg_r = sum(c[0] for c in coords) / len(coords)
    avg_c = sum(c[1] for c in coords) / len(coords)
    return (round(avg_r), round(avg_c))

def bounding_box(coords):
    if not coords:
        return (0, 0, 0, 0)
    min_r = min(c[0] for c in coords)
    max_r = max(c[0] for c in coords)
    min_c = min(c[1] for c in coords)
    max_c = max(c[1] for c in coords)
    return (min_r, min_c, max_r, max_c)

def component_coords(grid, color):
    """Get all coords of connected components of a color"""
    result = []
    visited = [[False]*24 for _ in range(25)]
    for r in range(25):
        for c in range(24):
            if grid[r][c] == color and not visited[r][c]:
                comp = []
                stack = [(r,c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < 25 and 0 <= nc < 24:
                            if grid[nr][nc] == color and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                result.append(comp)
    return result

